after.rawRule:
.linkPrimarySm {
  font-size: var(--mantine-font-size-sm);
  line-height: 1.25rem; /* design-tokens-allow: line-height: 1.25rem — Tailwind's text-sm paired line-height (20px), verbatim from the built CSS; set explicitly rather than relying on inheriting from the parent Text, since a bare <button> is not guaranteed to inherit it */
  color: var(--primary);
  text-decoration-line: underline;
  font-weight: 500;
  transition-property: color, background-color, border-color, outline-color, text-decoration-color, fill, stroke;
  transition-timing-function: var(--default-transition-timing-function);
  transition-duration: var(--default-transition-duration); /* design-tokens-allow: var(--default-transition-duration) — Tailwind-internal token (tailwindcss@4.3.0's own theme default); the static scanner cannot see through the opaque `@import "tailwindcss"` */
}

.orSeparatorLabelWrap {
  position: relative;
  display: flex;
  justify-content: center;
  font-size: var(--mantine-font-size-xs);
  line-height: 1rem; /* design-tokens-allow: line-height: 1rem — Tailwind's text-xs paired line-height (16px), verbatim from the built CSS; no token equals this exact per-utility pairing */
  text-transform: uppercase;
}

before.rawRule:
.transition-colors {
    transition-property: color, background-color, border-color, outline-color, text-decoration-color, fill, stroke, --tw-gradient-from, --tw-gradient-via, --tw-gradient-to;
    transition-timing-function: var(--tw-ease, var(--default-transition-timing-function));
    transition-duration: var(--tw-duration, var(--default-transition-duration));
  }

